mapper.select:
		SELECT 
		       FINPROD_MARKET_ID id,
               FINPROD_ABBR text/*modify by liupeilin*/
               /*多级法人改造，增加FIN_PRODUCT.FINPROD_ID查询字段 add by caojin 2020/6/9 start  */
		       ,FINPROD_ID finprodId
		       /*多级法人改造，增加FIN_PRODUCT.FINPROD_ID查询字段 add by caojin 2020/6/9 end  */
		FROM 
		       FIN_PRODUCT 
		WHERE  
		      1=1

		       AND PROFIT_TYPE=#{profitType}

		       AND FINPROD_TYPE2=#{TYPE_TOUGUAN_F17}
		       AND FINPROD_MARKET_ID IS NOT NULL

		       	AND (FINPROD_MARKET_ID like concat(concat('%', #{search,jdbcType=VARCHAR}),'%')

		       	)


		           AND FINPROD_MARKET_ID = #{initValue}

		SELECT 
		       FINPROD_ID finprodId,
		       VAL_DATE valDate,
		       VALUATION netValue
        FROM 
               FIN_PRODUCT_VALUATION 
        WHERE 
               FINPROD_ID=#{finprodId} 
               AND FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
               AND to_char(VAL_DATE,'yyyy-MM-dd') = #{valDate}

select A.FINPROD_ID finprodId
from FIN_PRODUCT_VALUATION A
where
	A.FINPROD_ID  =	#{finprodId,jdbcType=VARCHAR}
AND
	A.VAL_DATE = #{valDate,jdbcType=DATE}
AND
	A.FINPROD_TYPE2=#{finprodType2,jdbcType=VARCHAR}

    	SELECT
    		FINPROD_MARKET_ID finprodId
		FROM
    		FIN_PRODUCT  FP
		WHERE
    	FP.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
		AND
    	FP.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
    	AND
    	FP.FINPROD_ABBR = #{finprodName,jdbcType=VARCHAR}
